+export function loadConfig(path: string): ConfigFile {
+  const content = require('fs').readFileSync(path, 'utf-8');
+  if (path.endsWith('.json')) {
+    return JSON.parse(content);
+  }
+  // 简化版 YAML 解析
+  const result: ConfigFile = {};
+  for (const line of content.split('\n')) {
+    const match = line.match(/^\s*(\w+):\s*(.+)\s*$/);
+    if (match) {
+      result[match[1]] = match[2].replace(/^['"]|['"]$/g, '');
+    }
+  }
+  return result;
+}
+
 export function printHelp(options: Option[]): void {
   console.log('用法: parse-args [选项]');
   for (const opt of options) {
     console.log(`  -${opt.alias}, --${opt.name}   ${opt.description}`);
   }
 }
+
+export function mergeConfig(
+  args: ParsedArgs,
+  config: ConfigFile,
+  options: Option[]
+): ParsedArgs {
+  const result = { ...args };
+  for (const opt of options) {
+    const configValue = config[opt.name];
+    if (
+      configValue !== undefined &&
+      !(opt.name + '_from' in result)
+    ) {
+      result[opt.name] = configValue as string | boolean;
+      result[opt.name + '_from'] = 'config';
+    }
+  }
+  return result;
+}
