index e69de3b..a1b2c3d 100644
--- a/src/json_parser.rs
+++ b/src/json_parser.rs
@@ -10,6 +10,25 @@ pub struct JsonParser {

 impl JsonParser {
+    fn parse_string(&mut self) -> Result<String, String> {
+        self.expect(b'"')?;
+        let mut result = String::new();
+        while self.peek() != b'"' && !self.is_eof() {
+            let ch = self.consume();
+            if ch == b'\\' {
+                let esc = self.consume();
+                match esc {
+                    b'"' => result.push('"'),
+                    b'\\' => result.push('\\'),
+                    b'/' => result.push('/'),
+                    b'b' => result.push('\u{0008}'),
+                    b'f' => result.push('\u{000C}'),
+                    b'n' => result.push('\n'),
+                    b'r' => result.push('\r'),
+                    b't' => result.push('\t'),
+                    b'u' => {
+                        let hex = self.consume_hex(4)?;
+                        result.push(char::from_u32(hex).unwrap());
+                    }
+                    _ => return Err(format!("非法转义字符: {}", esc as char)),
+                }
+            } else {
+                result.push(ch as char);
+            }
+        }
+        self.expect(b'"')?;
+        Ok(result)
+    }
+
+    fn consume_hex(&mut self, n: usize) -> Result<u32, String> {
+        let mut value: u32 = 0;
+        for _ in 0..n {
+            let ch = self.consume();
+            let digit = match ch {
+                b'0'..=b'9' => (ch - b'0') as u32,
+                b'a'..=b'f' => (ch - b'a' + 10) as u32,
+                b'A'..=b'F' => (ch - b'A' + 10) as u32,
+                _ => return Err("非法十六进制字符".into()),
+            };
+            value = value * 16 + digit;
+        }
+        Ok(value)
+    }
+    // ... 省略其余实现
+}
