+++ b/tests/json_parser_test.rs
@@ -0,0 +1,67 @@
+mod json_parser;
+
+use json_parser::JsonParser;
+
+#[test]
+fn test_parse_null() {
+    let mut parser = JsonParser::new("null");
+    assert!(matches!(parser.parse().unwrap(), JsonValue::Null));
+}
+
+#[test]
+fn test_parse_bool() {
+    let mut parser = JsonParser::new("true");
+    assert!(matches!(parser.parse().unwrap(), JsonValue::Bool(true)));
+}
+
+#[test]
+fn test_parse_number() {
+    let mut parser = JsonParser::new("42.5");
+    assert!(matches!(parser.parse().unwrap(), JsonValue::Number(n) if n == 42.5));
+}
+
+#[test]
+fn test_parse_string() {
+    let mut parser = JsonParser::new("\"hello\"");
+    assert!(matches!(parser.parse().unwrap(), JsonValue::String(s) if s == "hello"));
+}
+
+#[test]
+fn test_parse_array() {
+    let mut parser = JsonParser::new("[1, 2, 3]");
+    assert!(matches!(parser.parse().unwrap(), JsonValue::Array(arr) if arr.len() == 3));
+}
+
+#[test]
+fn test_parse_object() {
+    let mut parser = JsonParser::new("{\"a\": 1}");
+    assert!(matches!(parser.parse().unwrap(), JsonValue::Object(obj) if obj.len() == 1));
+}
+
+#[test]
+fn test_parse_escape() {
+    let mut parser = JsonParser::new("\"a\\nb\\tc\"");
+    assert!(matches!(parser.parse().unwrap(), JsonValue::String(s) if s == "a\nb\tc"));
+}
+
+#[test]
+fn test_parse_invalid_json() {
+    let mut parser = JsonParser::new("{\"a\": }");
+    assert!(parser.parse().is_err());
+}
+

